#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
vector<string>items(n);
for(int i=0;i<n;++i)cin>>items[i];
string rule;cin>>rule;
size_t pos=rule.find(':');
string key=rule.substr(0,pos),val=rule.substr(pos+1);
int idx=(key=="type")?0:(key=="color"?1:2);
int cnt=0;
for(auto&it:items){
size_t p1=it.find(':'),p2=it.find(':',p1+1);
string segs[3]={it.substr(0,p1),it.substr(p1+1,p2-p1-1),it.substr(p2+1)};
if(segs[idx]==val)++cnt;}
printf("%d\n",cnt);return 0;}

